// Package headers names the L7 routing and auth headers (client → proxy) and the proxy-origin response marker.
package headers

const (
	TargetHost   = "X-L7-Target-Host"
	TargetScheme = "X-L7-Target-Scheme"
	ProxyToken   = "X-L7-Proxy-Token"
	Hops         = "X-L7-Hops"
)

// Proxy-to-client response header.
const (
	// ProxyOrigin marks a response generated by the proxy itself (an error envelope),
	// as opposed to one relayed from the upstream. Its value is ProxyOriginValue.
	ProxyOrigin      = "X-L7-Proxy"
	ProxyOriginValue = "1"
)
